CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE immutable_ai_audit_ledger (
  seq_id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  trace_id         UUID NOT NULL,
  tenant_id        UUID NOT NULL,
  actor_user_id    TEXT NOT NULL,
  prompt_version   TEXT NOT NULL,
  rag_chunk_hashes JSONB NOT NULL DEFAULT '[]'::jsonb,
  hitl_approver_id TEXT,
  target_table     TEXT NOT NULL,
  record_id        TEXT NOT NULL,
  operation        TEXT NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
  before_state     JSONB,
  after_state      JSONB,
  prev_hash        TEXT NOT NULL,
  entry_hash       TEXT NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

-- 1. KHOA TUYET DOI QUYEN SUA VA XOA TREN BANG AUDIT
REVOKE UPDATE, DELETE, TRUNCATE ON immutable_ai_audit_ledger FROM PUBLIC;

CREATE OR REPLACE FUNCTION deny_audit_mutation() RETURNS TRIGGER AS $$
BEGIN
  RAISE EXCEPTION 'IMMUTABILITY_VIOLATION: Bang immutable_ai_audit_ledger chi cho phep INSERT.';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_block_audit_update_delete
  BEFORE UPDATE OR DELETE ON immutable_ai_audit_ledger
  FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();

-- 2. NOI CHUOI SHA-256 HASH CHAIN TU DONG KHI GHI
CREATE OR REPLACE FUNCTION compute_audit_hash_chain() RETURNS TRIGGER AS $$
DECLARE
  last_hash TEXT;
  raw_input TEXT;
BEGIN
  -- Khoa tuan tu ngan race condition lam tach nhanh chuoi hash
  PERFORM pg_advisory_xact_lock(hashtext('immutable_ai_audit_ledger_chain'));
  SELECT entry_hash INTO last_hash
    FROM immutable_ai_audit_ledger
    ORDER BY seq_id DESC LIMIT 1;

  NEW.prev_hash := COALESCE(last_hash, repeat('0', 64));
  raw_input := concat_ws('|',
    NEW.prev_hash, NEW.trace_id::text, NEW.tenant_id::text,
    NEW.actor_user_id, NEW.prompt_version, NEW.target_table,
    NEW.record_id, NEW.operation,
    COALESCE(NEW.before_state::text, 'null'),
    COALESCE(NEW.after_state::text, 'null')
  );
  NEW.entry_hash := encode(digest(raw_input, 'sha256'), 'hex');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_hash_chain
  BEFORE INSERT ON immutable_ai_audit_ledger
  FOR EACH ROW EXECUTE FUNCTION compute_audit_hash_chain();

-- 3. TRIGGER CHUP BEFORE/AFTER DIFF CHO BANG NGHIEP VU (VD: crm_leads)
CREATE OR REPLACE FUNCTION audit_agent_row_change() RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO immutable_ai_audit_ledger (
    trace_id, tenant_id, actor_user_id, prompt_version,
    rag_chunk_hashes, hitl_approver_id, target_table, record_id,
    operation, before_state, after_state
  ) VALUES (
    COALESCE(NULLIF(current_setting('app.trace_id', true), ''), gen_random_uuid()::text)::uuid,
    COALESCE(NEW.tenant_id, OLD.tenant_id),
    COALESCE(NULLIF(current_setting('app.actor_id', true), ''), 'system_unknown'),
    COALESCE(NULLIF(current_setting('app.prompt_version', true), ''), 'v0'),
    COALESCE(NULLIF(current_setting('app.rag_chunks', true), ''), '[]')::jsonb,
    NULLIF(current_setting('app.hitl_approver', true), ''),
    TG_TABLE_NAME,
    COALESCE(NEW.id::text, OLD.id::text),
    TG_OP,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );
  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;
